<script setup lang="ts">
import{computed,onMounted,onBeforeUnmount,ref,watch,nextTick}from'vue';
import ServiceIcon from './ServiceIcon.vue';
import {withOperationTimeout} from './operation-timeout';
const operationAttempt=ref<{payload:string;id:string}|null>(null);let periodic:ReturnType<typeof setInterval>|undefined;
const props=defineProps<{load:(page?:number,filters?:Record<string,string>)=>Promise<any>;send:(input:Record<string,unknown>)=>Promise<any>;resolve?:(input:Record<string,unknown>)=>Promise<any>;resolveQueued?:(id:string)=>Promise<any>;initial?:any;language?:string}>();
const tr=(id:string,en:string)=>props.language==='en'?en:id;
const data=ref<any>(props.initial??null),busy=ref(false),error=ref(''),notice=ref(''),panel=ref('orders'),receipt=ref<any>(null),selected=ref<any>(null),payment=ref(''),shiftCash=ref(''),billingPeriod=ref('');
const page=ref(1), search=ref(''), statusFilter=ref(''), resourceFilter=ref(''), dateFrom=ref(''), dateTo=ref('');
const appliedFilters=ref<Record<string,string>>({});
const closingReport=ref<any>(props.initial?.last_closing??null), printMode=ref<'order'|'shift'|null>(null);
const visibleOrders=computed(()=>{
 if(data.value?.search_supported)return data.value.orders??[];
 const term=search.value.trim().toLocaleLowerCase();
 return (data.value?.orders??[]).filter((o:any)=>(!statusFilter.value||o.status===statusFilter.value)&&(!resourceFilter.value||o.resource_id===resourceFilter.value)&&(!term||[o.id,o.customer_name,o.contact,data.value.resources.find((r:any)=>r.id===o.resource_id)?.name].some(v=>String(v??'').toLocaleLowerCase().includes(term))));
});
async function applyFilters(){if(busy.value)return;if(dateFrom.value&&dateTo.value&&dateTo.value<dateFrom.value){error.value=tr('Tanggal akhir harus sama atau setelah tanggal awal.','End date must be on or after start date.');return;}appliedFilters.value={q:search.value.trim(),status:statusFilter.value,resource_id:resourceFilter.value,from:dateFrom.value,to:dateTo.value};page.value=1;await refresh();}
async function openWorkload(status='',resourceId=''){if(busy.value)return;search.value='';statusFilter.value=status;resourceFilter.value=resourceId;dateFrom.value='';dateTo.value='';panel.value='orders';await applyFilters();}
const statusTotal=computed(()=>Object.values(data.value?.insights?.status_counts??{}).reduce((sum:number,value:any)=>sum+Number(value),0));
function clearFilters(){if(busy.value)return;search.value='';statusFilter.value='';resourceFilter.value='';dateFrom.value='';dateTo.value='';void applyFilters();}


const resource=ref({id:'',version:0,name:'',unit:'kg',rate:'',enabled:true});const form=ref({resource_id:'',customer_name:'',contact:'',start_date:new Date().toISOString().slice(0,10),end_date:new Date().toISOString().slice(0,10),quantity:'1'});
const type=computed(()=>data.value?.type??'laundry');const laundry=computed(()=>type.value==='laundry');const title=computed(()=>laundry.value?'Laundry':type.value==='boarding'?tr('Kosan','Boarding house'):'Homestay');
const statusNames:Record<string,[string,string]>={received:['Diterima','Received'],washing:['Dicuci','Washing'],drying:['Dikeringkan','Drying'],ironing:['Disetrika','Ironing'],ready:['Siap diambil','Ready'],collected:['Diambil','Collected'],reserved:['Dipesan','Reserved'],checked_in:['Dihuni','Checked in'],checked_out:['Selesai','Checked out'],cancelled:['Dibatalkan','Cancelled']};
const states=computed(()=>laundry.value?['received','washing','drying','ironing','ready','collected']:['reserved','checked_in','checked_out']);const nextState=(s:string)=>states.value[states.value.indexOf(s)+1];
const money=(v:number)=>`${data.value?.symbol??data.value?.currency??''} ${new Intl.NumberFormat(props.language==='en'?'en-US':'id-ID',{minimumFractionDigits:data.value?.scale??0,maximumFractionDigits:data.value?.scale??0}).format(Number(v)/10**(data.value?.scale??0))}`;
function numeric(raw:string,scale:number){if(!new RegExp(`^\\d+(?:[.,]\\d{1,${Math.max(1,scale)}})?$`).test(raw)||scale===0&&/[.,]/.test(raw))throw Error('INVALID_NUMERIC_VALUE');const [w,f='']=raw.replace(',','.').split('.');const v=Number(w)*10**scale+Number(f.padEnd(scale,'0'));if(!Number.isSafeInteger(v)||v<0||v>100000000000)throw Error('INVALID_NUMERIC_VALUE');return v;}
const invoices=computed(()=>data.value?.invoices?.filter((i:any)=>i.order_id===selected.value?.id)??[]);
const active=computed(()=>data.value?.summary?.active_orders??data.value?.orders?.filter((o:any)=>!['collected','checked_out','cancelled'].includes(o.status)).length??0);
const due=computed(()=>data.value?.summary?.outstanding_atomic??data.value?.invoices?.filter((i:any)=>data.value.orders.some((o:any)=>o.id===i.order_id&&o.status!=='cancelled')).reduce((n:number,i:any)=>n+Number(i.total_atomic)-Number(i.paid_atomic),0)??0);
async function refresh(){if(busy.value)return;busy.value=true;error.value='';try{data.value=await withOperationTimeout(props.load(page.value,appliedFilters.value));page.value=data.value.pagination?.page??page.value;if(!closingReport.value&&data.value.last_closing)closingReport.value=data.value.last_closing;if(selected.value)selected.value=data.value.orders.find((o:any)=>o.id===selected.value.id)??null;}catch(e){error.value=tr('Data belum dapat dimuat. Periksa koneksi dan coba lagi.','Unable to load data. Check connection and retry.')+' · '+String(e);}finally{busy.value=false;}}
async function command(action:string,fields:Record<string,unknown>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{const payload=JSON.stringify({action,...fields});if(operationAttempt.value&&operationAttempt.value.payload!==payload)throw Error('PREVIOUS_OPERATION_UNCONFIRMED_RETRY_OR_REVIEW');operationAttempt.value??={payload,id:crypto.randomUUID()};persistAttempt();const result=await withOperationTimeout(props.send({action,operation_id:operationAttempt.value.id,...fields}));operationAttempt.value=null;persistAttempt();if(result.queued){data.value=await withOperationTimeout(props.load(page.value,appliedFilters.value));notice.value=tr('Tersimpan sebagai antrean lokal. Belum dikonfirmasi server; reservasi belum dijamin tersedia.','Saved to local queue. Not server-confirmed; reservations are not guaranteed.');return;}receipt.value=result.record;if(action==='shift.close')closingReport.value=result.record;if(action==='shift.open'||action==='shift.close')shiftCash.value='';if(action==='resource.save'){resource.value.id=result.record.id;resource.value.version=result.record.version;}if(action==='order.create')page.value=1;data.value=page.value===1&&!Object.values(appliedFilters.value).some(Boolean)?(result.workspace??await withOperationTimeout(props.load(1,appliedFilters.value))):await withOperationTimeout(props.load(page.value,appliedFilters.value));if(selected.value)selected.value=data.value.orders.find((o:any)=>o.id===selected.value.id)??null;notice.value=tr('Berhasil disimpan dan dikonfirmasi server.','Saved and confirmed by the server.');if(action==='order.create'){form.value.customer_name='';form.value.contact='';}payment.value='';}catch(e){error.value=tr('Belum berhasil. Periksa status terbaru sebelum mengulangi.','Not completed. Check the latest state before retrying.')+' · '+String(e);}finally{busy.value=false;}}
function attemptKey(){return 'oneqay.service.pending.'+JSON.stringify(data.value?.scope??{});}
function persistAttempt(){if(!props.resolve)return;try{if(operationAttempt.value)sessionStorage.setItem(attemptKey(),JSON.stringify(operationAttempt.value));else sessionStorage.removeItem(attemptKey());}catch{error.value=tr('Penyimpanan pemulihan browser tidak tersedia. Jangan tutup halaman sebelum status dikonfirmasi.','Browser recovery storage is unavailable. Keep this page open until confirmed.');}}
async function restoreAttempt(){if(!data.value)await refresh();if(!props.resolve)return;try{const raw=sessionStorage.getItem(attemptKey());if(raw){const v=JSON.parse(raw);if(typeof v.payload==='string'&&typeof v.id==='string')operationAttempt.value=v;}}catch{error.value='PENDING_OPERATION_STORAGE_INVALID';}}
async function retryAttempt(){const v=operationAttempt.value;if(!v)return;const {action,...fields}=JSON.parse(v.payload);await command(action,fields);}
async function resolveAttempt(id?:string){if(busy.value)return;if(!confirm(tr('Server akan mempertahankan transaksi yang sudah tercatat, atau membatalkan permintaan yang belum tercatat. Lanjutkan?','The server will preserve a recorded transaction, or cancel an unrecorded request. Continue?')))return;busy.value=true;try{const v=operationAttempt.value;const result=id&&props.resolveQueued?await withOperationTimeout(props.resolveQueued(id)):v&&props.resolve?await withOperationTimeout(props.resolve({...JSON.parse(v.payload),operation_id:v.id})):null;if(!result)throw Error('OPERATION_NOT_FOUND');operationAttempt.value=null;persistAttempt();data.value=result.workspace;receipt.value=result.record;if(result.record?.variance_atomic!==undefined)closingReport.value=result.record;notice.value=result.record?.rejected?tr('Permintaan belum tercatat dan telah dibatalkan.','The unrecorded request has been cancelled.'):tr('Transaksi sudah tercatat dan dipertahankan.','The transaction was already recorded and has been preserved.');}catch(e){error.value=String(e);}finally{busy.value=false;}}
const dialog=ref<HTMLElement|null>(null);let previousFocus:HTMLElement|null=null;
watch(selected,async(value)=>{if(value){previousFocus=document.activeElement as HTMLElement;await nextTick();dialog.value?.querySelector<HTMLElement>('button')?.focus();}else previousFocus?.focus();});
function dialogKeys(e:KeyboardEvent){if(e.key==='Escape'&&!busy.value)selected.value=null;if(e.key!=='Tab')return;const items=dialog.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),a[href]');if(!items?.length)return;const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){last.focus();e.preventDefault();}else if(!e.shiftKey&&document.activeElement===last){first.focus();e.preventDefault();}}
function saveResource(){try{void command('resource.save',{id:resource.value.id,version:resource.value.version,name:resource.value.name,unit:laundry.value?resource.value.unit:type.value==='boarding'?'month':'night',rate_atomic:numeric(resource.value.rate,data.value.scale),currency:data.value.currency,scale:data.value.scale,enabled:resource.value.enabled});}catch(e){error.value=String(e);}}
function editResource(r:any){resource.value={id:r.id,version:Number(r.version),name:r.name,unit:r.unit,rate:String(Number(r.rate_atomic)/10**data.value.scale),enabled:!!r.enabled};}
function clearResource(){resource.value={id:'',version:0,name:'',unit:'kg',rate:'',enabled:true};}
function create(){try{void command('order.create',{...form.value,quantity:undefined,quantity_milli:laundry.value?numeric(form.value.quantity,3):1000});}catch(e){error.value=String(e);}}
function pay(id:string){try{void command('payment.record',{invoice_id:id,amount_atomic:numeric(payment.value,data.value.scale)});}catch(e){error.value=String(e);}}
function shift(){try{void command(data.value.shift?'shift.close':'shift.open',{[data.value.shift?'closing_atomic':'opening_atomic']:numeric(shiftCash.value,data.value.scale)});}catch(e){error.value=String(e);}}
function movePage(delta:number){page.value=Math.max(1,page.value+delta);selected.value=null;void refresh();}
async function print(mode:'order'|'shift'){
 printMode.value=mode;await nextTick();window.print();
}
function afterPrint(){printMode.value=null;}
onMounted(()=>window.addEventListener('afterprint',afterPrint));
onBeforeUnmount(()=>window.removeEventListener('afterprint',afterPrint));
function reconnect(){void refresh();}onMounted(()=>{void restoreAttempt();periodic=setInterval(()=>{if(!busy.value)void refresh();},15000);window.addEventListener('online',reconnect);});onBeforeUnmount(()=>{clearInterval(periodic);window.removeEventListener('online',reconnect);});
</script>
<template><main class="service-workspace" :data-business-type="type"><header class="service-head"><div><span class="service-eyebrow">{{data?.profile?.name??'oneQay'}} · {{tr('RUANG KERJA TERPISAH','ISOLATED WORKSPACE')}}</span><h1><span class="service-type-icon"><ServiceIcon :name="laundry?'washing-machine':type==='boarding'?'building-2':'bed-double'"/></span>{{title}}</h1><p>{{laundry?tr('Dari penerimaan cucian sampai pengambilan, setiap langkah tercatat.','Track every step from intake to collection.'):type==='boarding'?tr('Kelola kamar, penghuni, dan tagihan sewa berkala.','Manage rooms, residents and periodic rent.'):tr('Reservasi, ketersediaan kamar, check-in, dan check-out dalam satu alur.','Reservations, room availability, check-in and check-out in one workflow.')}}</p></div><button @click="refresh" :disabled="busy"><ServiceIcon name="refresh-cw"/> {{tr('Perbarui','Refresh')}}</button></header><p v-if="error" role="alert" class="service-error">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="busy" class="service-progress" role="status" aria-live="polite"><ServiceIcon name="loader-circle"/>{{tr('Memproses, mohon tunggu…','Processing, please wait…')}}</p><section v-if="operationAttempt" class="service-panel"><h2>{{tr('Permintaan belum terkonfirmasi','Unconfirmed request')}}</h2><code>{{operationAttempt.id}}</code><p>{{tr('Coba ulang dengan referensi yang sama atau periksa dan batalkan melalui server.','Retry with the same reference or reconcile and cancel through the server.')}}</p><button :disabled="busy" @click="retryAttempt">{{tr('Coba ulang','Retry')}}</button><button v-if="resolve" :disabled="busy" @click="resolveAttempt()">{{tr('Periksa / batalkan aman','Reconcile / cancel safely')}}</button></section><template v-if="data"><p v-if="data.connection" role="status">{{data.connection==='online'?'● Online':tr('○ Offline · data terakhir dari perangkat','○ Offline · last cached data')}}</p><section v-if="data.local_queue?.length" class="service-panel"><h2>{{tr('Antrean sinkronisasi terpisah','Separate synchronization queue')}} ({{data.local_queue.length}})</h2><p>{{tr('Pesanan lokal belum menjadi konfirmasi server. Konflik harus diperiksa sebelum dikirim ulang.','Local orders are not server confirmations. Review conflicts before retrying.')}}</p><p v-for="q in data.local_queue" :key="q.request.command.operation_id">{{q.request.command.action}} · {{q.state}} · <code>{{q.request.command.operation_id}}</code> <button v-if="resolveQueued" :disabled="busy" @click="resolveAttempt(q.request.command.operation_id)">{{tr('Periksa / batalkan','Reconcile / cancel')}}</button></p></section><div class="service-kpis"><article><small>{{data.summary?tr('Pesanan aktif di outlet ini','Active orders at this outlet'):tr('Pesanan aktif pada daftar ini','Active orders on this page')}}</small><strong>{{active}}</strong></article><article><small>{{data.summary?tr('Sisa tagihan di outlet ini','Outstanding at this outlet'):tr('Sisa tagihan pada daftar ini','Outstanding on this page')}}</small><strong>{{money(due)}}</strong></article><article><small>{{tr('Kasir','Register')}}</small><strong>{{data.shift?tr('Shift terbuka','Shift open'):tr('Belum dibuka','Not opened')}}</strong></article></div><nav class="service-tabs"><button v-for="(text,key) in {orders:tr('Operasional','Operations'),...(data.insights?{insights:tr('Ikhtisar usaha','Business overview')}:{}),create:laundry?tr('Terima cucian','New laundry'):tr('Reservasi baru','New reservation'),resources:laundry?tr('Layanan & tarif','Services & rates'):tr('Kamar & tarif','Rooms & rates'),shift:tr('Buka / tutup kas','Open / close register')}" :key="key" @click="panel=key" :aria-current="panel===key?'page':undefined"><ServiceIcon :name="key==='resources'?(laundry?'washing-machine':'bed-double'):key==='shift'?'wallet':'receipt-text'"/> {{text}}</button></nav>
<section v-if="panel==='insights'&&data.insights" class="service-panel"><h2>{{tr('Ikhtisar operasional outlet','Outlet operations overview')}}</h2><p>{{tr('Seluruh pesanan outlet, terpisah menurut jenis usaha.','All outlet orders, isolated by business type.')}} {{tr('Tanggal acuan','As of')}}: {{data.insights.as_of}}</p><div class="service-grid"><article><h3>{{tr('Sebaran status pesanan','Orders by status')}}</h3><p v-if="!statusTotal">{{tr('Belum ada pesanan yang tercatat.','No orders recorded yet.')}}</p><button v-for="(count,state) in data.insights.status_counts" :key="state" class="service-status-row" :disabled="busy" @click="openWorkload(String(state))"><span>{{statusNames[String(state)]?.[language==='en'?1:0]??state}}</span><strong>{{count}}</strong><span class="service-status-track" aria-hidden="true"><span :style="{width:(Number(count)/Math.max(1,statusTotal)*100)+'%'}"></span></span></button></article><article><h3>{{laundry?tr('Pesanan melewati estimasi selesai','Orders past estimated completion'):tr('Pesanan melewati tanggal akhir','Orders past end date')}}</h3><strong class="service-insight-number">{{data.insights.overdue_orders}}</strong><p>{{laundry?tr('Periksa cucian yang belum diambil atau belum selesai sesuai jadwal.','Review laundry that has not been collected or completed on schedule.'):tr('Periksa penghuni atau reservasi yang belum diselesaikan setelah tanggal akhir.','Review stays or reservations not completed after their end date.')}}</p><p>{{tr('Sisa seluruh tagihan','Total outstanding')}}: <strong>{{money(due)}}</strong></p></article></div><h3>{{laundry?tr('Beban layanan aktif','Active service workload'):tr('Pesanan aktif per kamar','Active orders by room')}}</h3><div class="service-table"><table><thead><tr><th>{{laundry?tr('Layanan','Service'):tr('Kamar','Room')}}</th><th>{{tr('Pesanan aktif','Active orders')}}</th><th>{{tr('Tindakan','Action')}}</th></tr></thead><tbody><tr v-for="r in data.resources" :key="r.id"><td>{{r.name}}<small v-if="!r.enabled">{{tr('Nonaktif untuk pesanan baru','Inactive for new orders')}}</small></td><td>{{data.insights.resource_workload[r.id]??0}}</td><td><button :disabled="busy" @click="openWorkload('',r.id)">{{tr('Lihat pesanan','View orders')}}</button></td></tr></tbody></table></div></section>
<section v-if="panel==='orders'" class="service-panel"><h2>{{tr('Aktivitas terbaru','Recent activity')}}</h2><form class="service-filters" @submit.prevent="applyFilters"><label>{{data.search_supported?tr('Cari seluruh pesanan','Search all orders'):tr('Cari pada halaman ini','Search this page')}}<input v-model="search" type="search" :placeholder="tr('Nama, kontak, nomor pesanan…','Name, contact, order reference…')"/></label><label>{{tr('Status pesanan','Order status')}}<select v-model="statusFilter" :aria-label="tr('Status pesanan','Order status')"><option value="">{{tr('Semua status','All statuses')}}</option><option v-for="state in [...states,'cancelled']" :key="state" :value="state">{{statusNames[state]?.[language==='en'?1:0]}}</option></select></label><label>{{laundry?tr('Layanan','Service'):tr('Kamar','Room')}}<select v-model="resourceFilter"><option value="">{{tr('Semua','All')}}</option><option v-for="r in data.resources" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label v-if="data.search_supported">{{tr('Tanggal mulai dari','Start date from')}}<input v-model="dateFrom" type="date"/></label><label v-if="data.search_supported">{{tr('Tanggal mulai sampai','Start date through')}}<input v-model="dateTo" type="date" :min="dateFrom"/></label><button v-if="data.search_supported" class="service-primary" :disabled="busy">{{tr('Terapkan filter','Apply filters')}}</button><button type="button" :disabled="busy" @click="clearFilters">{{tr('Reset filter','Reset filters')}}</button></form><p v-if="data.connection==='offline'">{{tr('Pencarian server memerlukan internet. Daftar ini adalah hasil terakhir yang tersimpan di perangkat.','Server search requires internet. This list is the last result cached on this device.')}}</p><p role="status">{{visibleOrders.length}} {{tr('pesanan ditampilkan dari','orders shown out of')}} {{data.search_supported?(data.pagination?.total??data.orders.length):data.orders.length}} {{data.search_supported?tr('hasil pencarian tersimpan','saved search results'):tr('pada halaman ini','on this page')}}</p><p v-if="data.orders.length&&!visibleOrders.length">{{tr('Belum ada hasil yang cocok. Ubah pencarian atau reset filter.','No matching results. Change your search or reset filters.')}}</p><p v-if="!data.orders.length">{{tr('Belum ada pesanan. Mulai dari layanan atau kamar, lalu buat pesanan pertama.','No orders yet. Create a service or room, then add your first order.')}}</p><div class="service-table"><table v-if="visibleOrders.length"><thead><tr><th>{{tr('Pelanggan / penghuni','Customer / resident')}}</th><th>{{tr('Periode','Period')}}</th><th>Status</th><th>{{tr('Nilai','Amount')}}</th><th></th></tr></thead><tbody><tr v-for="o in visibleOrders" :key="o.id"><td>{{o.customer_name}}<small>{{data.resources.find((r:any)=>r.id===o.resource_id)?.name}}</small></td><td>{{o.start_date}} → {{o.end_date}}</td><td><span class="service-badge">{{statusNames[o.status]?.[language==='en'?1:0]??o.status}}</span></td><td>{{money(o.total_atomic)}}</td><td><button @click="selected=o">{{tr('Kelola','Manage')}}</button></td></tr></tbody></table></div><div v-if="data.pagination?.total>100" class="service-pagination"><button :disabled="busy||page<=1" @click="movePage(-1)">{{tr('Sebelumnya','Previous')}}</button><span>{{tr('Halaman','Page')}} {{page}} / {{Math.ceil(data.pagination.total/100)}}</span><button :disabled="busy||page*100>=data.pagination.total" @click="movePage(1)">{{tr('Berikutnya','Next')}}</button></div></section>
<form v-if="panel==='create'" class="service-panel service-form" @submit.prevent="create"><h2>{{laundry?tr('Penerimaan cucian','Laundry intake'):tr('Reservasi kamar','Room reservation')}}</h2><label>{{laundry?tr('Layanan','Service'):tr('Kamar','Room')}}<select v-model="form.resource_id" required><option value="">{{tr('Pilih','Select')}}</option><option v-for="r in data.resources.filter((r:any)=>r.enabled)" :key="r.id" :value="r.id">{{r.name}} · {{money(r.rate_atomic)}} / {{r.unit}}</option></select></label><label>{{tr('Nama pelanggan / penghuni','Customer / resident name')}}<input v-model="form.customer_name" required maxlength="100"/></label><label>{{tr('Kontak','Contact')}}<input v-model="form.contact" type="tel" required maxlength="32"/></label><div class="service-grid"><label>{{laundry?tr('Tanggal diterima','Intake date'):tr('Mulai menginap','Arrival date')}}<input v-model="form.start_date" type="date" required/></label><label>{{laundry?tr('Estimasi selesai','Estimated completion'):tr('Tanggal akhir (tidak termasuk)','End date (exclusive)')}}<input v-model="form.end_date" type="date" :min="form.start_date" required/></label></div><label v-if="laundry">{{tr('Berat kg / jumlah potong','Weight kg / item count')}}<input v-model="form.quantity" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,3})?" required/></label><p>{{tr('Reservasi kamar diperiksa kembali oleh server saat disimpan. Tagihan kos berikutnya dibuat per periode dari detail kontrak.','Room availability is rechecked by the server when saving. Create subsequent boarding invoices by period in contract details.')}}</p><button class="service-primary" :disabled="busy">{{tr('Simpan pesanan','Save order')}}</button></form>
<section v-if="panel==='resources'" class="service-panel"><h2>{{laundry?tr('Layanan','Services'):tr('Kamar','Rooms')}}</h2><ul><li v-for="r in data.resources" :key="r.id">{{r.name}} · {{money(r.rate_atomic)}} / {{r.unit}} <span v-if="!r.enabled">{{tr('Nonaktif','Inactive')}}</span> <button v-if="data.can_configure" @click="editResource(r)">{{tr('Ubah','Edit')}}</button></li></ul><form v-if="data.can_configure" class="service-form" @submit.prevent="saveResource"><h3>{{resource.version?tr('Ubah layanan / kamar','Edit service / room'):tr('Tambah','Add')}}</h3><label>{{tr('Nama','Name')}}<input v-model="resource.name" required maxlength="100"/></label><label v-if="laundry">{{tr('Satuan','Unit')}}<select v-model="resource.unit" :disabled="resource.version>0"><option value="kg">kg</option><option value="piece">{{tr('Potong','Piece')}}</option></select></label><label>{{tr('Tarif','Rate')}} ({{data.currency}})<input v-model="resource.rate" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" required/></label><label class="service-checkbox"><input v-model="resource.enabled" type="checkbox"/>{{tr('Aktif untuk pesanan baru','Active for new orders')}}</label><button class="service-primary" :disabled="busy">{{tr('Simpan layanan / kamar','Save service / room')}}</button><button type="button" @click="clearResource">{{tr('Buat baru','Create new')}}</button></form><p v-else>{{tr('Layanan dan tarif dikelola pemilik bisnis di web.','The business owner manages services and rates on the web.')}}</p></section>
<form v-if="panel==='shift'" class="service-panel service-form" @submit.prevent="shift"><h2>{{data.shift?tr('Tutup kasir','Close register'):tr('Buka kasir','Open register')}}</h2><p>{{tr('Kas dan laporan shift khusus jenis usaha ini, terpisah dari kas POS barang.','This workflow has its own cash and shift report, separate from retail POS.')}}</p><label>{{data.shift?tr('Kas fisik akhir','Closing cash counted'):tr('Kas awal','Opening cash')}}<input v-model="shiftCash" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" required/></label><button class="service-primary" :disabled="busy">{{tr('Simpan','Save')}}</button><section v-if="data.closing_history?.length" class="service-closing-history"><h3>{{tr('Riwayat tutup kas saya','My closing history')}}</h3><p>{{tr('20 laporan terakhir pada perangkat ini. Pilih laporan untuk mencetak ulang.','Last 20 reports on this device. Select a report to reprint.')}}</p><label>{{tr('Pilih laporan tutup kas','Select closing report')}}<select :value="closingReport?.id??''" @change="closingReport=data.closing_history.find((r:any)=>r.id===($event.target as HTMLSelectElement).value)"><option v-for="report in data.closing_history" :key="report.id" :value="report.id">{{new Date(report.closed_at*1000).toLocaleString(language==='en'?'en-GB':'id-ID')}} · {{report.id.slice(-8)}}</option></select></label></section><div v-if="closingReport?.variance_atomic!==undefined" class="service-report"><h3>{{tr('Laporan tutup kas','Register closing report')}}</h3><p>{{tr('Awal','Opening')}}: {{money(closingReport.opening_atomic)}}</p><p>{{tr('Penerimaan','Received')}}: {{money(closingReport.received_atomic)}}</p><p>{{tr('Diharapkan','Expected')}}: {{money(closingReport.expected_atomic)}}</p><p>{{tr('Dihitung','Counted')}}: {{money(closingReport.counted_atomic)}}</p><p>{{tr('Selisih','Variance')}}: {{money(closingReport.variance_atomic)}}</p><button type="button" @click="print('shift')">{{tr('Cetak / simpan PDF','Print / save PDF')}}</button></div></form>
<div v-if="selected" class="service-overlay"><section ref="dialog" @keydown="dialogKeys" class="service-dialog" role="dialog" aria-modal="true" aria-labelledby="order-title"><button class="service-close" @click="selected=null"><ServiceIcon name="x"/> {{tr('Tutup','Close')}}</button><h2 id="order-title">{{selected.customer_name}}</h2><p>{{selected.contact}} · {{selected.start_date}} → {{selected.end_date}}</p><p>{{tr('Nomor','Reference')}}: {{selected.id}}</p><p>{{statusNames[selected.status]?.[language==='en'?1:0]??selected.status}}</p><template v-for="invoice in invoices" :key="invoice.id"><div class="service-invoice"><h3>{{tr('Tagihan','Invoice')}} · {{invoice.period}}</h3><p>{{money(invoice.total_atomic)}} · {{tr('Dibayar','Paid')}} {{money(invoice.paid_atomic)}}</p><form v-if="selected.status!=='cancelled'&&Number(invoice.paid_atomic)<Number(invoice.total_atomic)" @submit.prevent="pay(invoice.id)"><label>{{tr('Pembayaran tunai','Cash payment')}}<input v-model="payment" type="text" inputmode="decimal" pattern="[0-9]+([.,][0-9]{1,4})?" required/></label><button :disabled="busy||!data.shift">{{tr('Catat pembayaran','Record payment')}}</button><small v-if="!data.shift">{{tr('Buka shift kasir terlebih dahulu.','Open the register shift first.')}}</small></form></div></template><form v-if="type==='boarding'&&['reserved','checked_in'].includes(selected.status)" @submit.prevent="command('invoice.create',{id:selected.id,version:Number(selected.version),period:billingPeriod})"><label>{{tr('Tanggal periode sewa berikutnya','Next rental period date')}}<input v-model="billingPeriod" type="date" required/></label><button :disabled="busy">{{tr('Buat tagihan periode','Create period invoice')}}</button></form><button v-if="nextState(selected.status)" class="service-primary" :disabled="busy" @click="command('order.transition',{id:selected.id,version:Number(selected.version),status:nextState(selected.status)})">{{tr('Lanjut ke','Continue to')}} {{statusNames[nextState(selected.status)]?.[language==='en'?1:0]}}</button><button v-if="['reserved','received'].includes(selected.status)" :disabled="busy" @click="command('order.transition',{id:selected.id,version:Number(selected.version),status:'cancelled'})">{{tr('Batalkan pesanan belum dibayar','Cancel unpaid order')}}</button><button @click="print('order')">{{tr('Cetak / PDF','Print / PDF')}}</button></section></div></template></main><Teleport to="body"><article v-if="printMode" class="service-print-document"><header><h1>{{data?.profile?.name??'oneQay'}}</h1><p>{{title}}</p></header><template v-if="printMode==='shift'&&closingReport"><h2>{{tr('Laporan tutup kas','Register closing report')}}</h2><p>{{tr('Nomor','Reference')}}: {{closingReport.id}}</p><p>{{tr('Petugas kasir','Cashier')}}: {{closingReport.cashier}}</p><p v-if="closingReport.closed_at">{{new Date(closingReport.closed_at*1000).toLocaleString(language==='en'?'en-GB':'id-ID')}}</p><dl><template v-for="(label,key) in {opening_atomic:tr('Kas awal','Opening cash'),received_atomic:tr('Penerimaan','Received'),expected_atomic:tr('Kas seharusnya','Expected cash'),counted_atomic:tr('Kas dihitung','Counted cash'),variance_atomic:tr('Selisih','Variance')}" :key="key"><dt>{{label}}</dt><dd>{{money(closingReport[key])}}</dd></template></dl></template><template v-else-if="selected"><h2>{{tr('Bukti pesanan','Order receipt')}}</h2><p>{{tr('Nomor','Reference')}}: {{selected.id}}</p><p>{{selected.customer_name}} · {{selected.contact}}</p><p>{{data.resources.find((r:any)=>r.id===selected.resource_id)?.name}}</p><p>{{selected.start_date}} → {{selected.end_date}}</p><p>{{statusNames[selected.status]?.[language==='en'?1:0]}}</p><section v-for="invoice in invoices" :key="invoice.id"><h3>{{tr('Tagihan periode','Invoice period')}}: {{invoice.period}}</h3><dl><dt>{{tr('Jumlah','Amount')}}</dt><dd>{{money(invoice.total_atomic)}}</dd><dt>{{tr('Dibayar','Paid')}}</dt><dd>{{money(invoice.paid_atomic)}}</dd><dt>{{tr('Sisa tagihan','Balance')}}</dt><dd>{{money(Number(invoice.total_atomic)-Number(invoice.paid_atomic))}}</dd></dl></section></template><footer>oneQay</footer></article></Teleport></template>
<style>
.service-print-document{display:none}
@media print{body:has(.service-print-document)>*:not(.service-print-document){display:none!important}.service-print-document{display:block!important;color:#202020;background:#FFFFFF;font:16px/1.5 system-ui}.service-print-document dl{display:grid;grid-template-columns:1fr 1fr;gap:8px}.service-print-document dd{margin:0;text-align:right}.service-print-document header,.service-print-document section{border-bottom:1px solid #EDEDED;padding-bottom:16px}.service-print-document footer{margin-top:24px}}
</style>
